A Monitor to Allocate Single Resource

monitor ResourceAllocator
{

boolean busy;

condition x;

void acquire(int time) {

if (busy)

x.wait(time);

busy = TRUE;

}

void release() {

busy = FALSE;

x.signal();

}
initialization code() {

busy = FALSE;

}
}

